
import type { MoneyMovementBlockedReasonInput } from './MoneyMovementBlockedReasonInput.js';
import type { NextActionInput } from './NextActionInput.js';

/** Merchant capability readiness for a payment or money movement capability. */ export type CapabilityInput = { /** Reasons this capability is blocked, pending, or not available. */ "blocked_reasons"?: Array<MoneyMovementBlockedReasonInput>; /** Flint-owned capability name. Payment capabilities describe transaction acceptance readiness; money movement capabilities describe payout and balance movement readiness. */ "capability": "accept_card_payments" | "save_payment_methods" | "accept_affirm_payments" | "receive_payouts" | "create_standard_payouts" | "manage_payout_destinations" | "manage_payout_settings"; /** Capability domain. API keys scoped to one domain only receive that domain when listing capabilities without a domain filter. */ "domain": "money_movement" | "payments"; /** Actions that can remediate or refresh this capability when Flint can suggest one. */ "next_actions"?: Array<NextActionInput>; /** RFC3339 timestamp for the source state used to evaluate this capability. Format: date-time. */ "observed_at"?: string | globalThis.Date; /** Merchant requirements that affect this capability. */ "requirements": { /** RFC3339 timestamp. Format: date-time. */ "current_deadline_at"?: string | globalThis.Date; "currently_due_fields"?: Array<string>; /** Normalized reason the related account requirements currently disable or block the capability. */ "disabled_reason"?: "account_attention_required" | "account_paused" | "account_rejected" | "account_requirements_due" | "account_under_review" | "requirements_past_due" | "requirements_pending_verification" | null; "eventually_due_fields"?: Array<string>; "past_due_fields"?: Array<string>; "pending_verification_fields"?: Array<string>; }; /** Current readiness status for this capability. */ "status": "ready" | "blocked" | "pending" | "not_available"; };
